window.HOEREN_TESTS[84] = {"id":"in-der-musikschule","name":"In der Musikschule","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Eltern: Das Schülerkonzert unserer Musikschule findet bald statt. Aber nicht am Freitag, sondern am Samstag um 17 Uhr in der Aula. Alle Kinder spielen ihr Lieblingsstück vor. Der Eintritt ist frei. Bitte kommen Sie pünktlich und schalten Sie Ihre Handys aus. Wir freuen uns auf Sie!","gender":"f","q":"Wann ist das Schülerkonzert?","opts":["Am Samstag.","Am Freitag.","Am Sonntag."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Ich will endlich Gitarre lernen, mein Traum seit Jahren. Die Musikschule bietet Kurse für Erwachsene an, auch für Anfänger. Man ist nie zu alt, sagt die Lehrerin. Hast du noch deine alte Gitarre? Kann ich die leihen, bis ich eine kaufe? Ruf zurück, danke!","gender":"m","q":"Was möchte Markus lernen?","opts":["Klavier.","Schlagzeug.","Gitarre."],"correct":2},{"transcript":"Achtung Schüler: Die Klavierlehrerin Frau Berg ist im Urlaub. Ihre Stunden fallen diese Woche aus. Wer möchte, kann bei Herrn Klein üben — er hat noch freie Termine am Nachmittag. Die Stunden werden nicht berechnet, wenn sie ausfallen. Ab nächster Woche ist Frau Berg wieder da. Danke!","gender":"m","q":"Warum fallen die Klavierstunden aus?","opts":["Die Lehrerin ist krank.","Die Lehrerin ist im Urlaub.","Das Klavier ist kaputt."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Hey, meine Tochter lernt jetzt Geige in der Musikschule und ist so glücklich! Sie übt jeden Tag, ganz ohne dass ich sie erinnern muss. Es ist zwar am Anfang nicht schön für die Ohren, aber sie wird schnell besser. Soll dein Sohn nicht auch ein Instrument lernen?","gender":"f","q":"Welches Instrument lernt Annas Tochter?","opts":["Geige.","Klavier.","Flöte."],"correct":0},{"transcript":"Liebe Interessenten: Bei uns kann man Instrumente erst ausprobieren, bevor man sich entscheidet. An einem Tag im Monat dürfen Kinder alle Instrumente testen — Klavier, Geige, Trompete und mehr. Ein Konzert hören Sie an dem Tag nicht, und Noten kaufen wir auch nicht. So findet jedes Kind das passende. Der Schnuppertag ist kostenlos. Melden Sie sich im Büro an!","gender":"f","q":"Was kann man am Schnuppertag machen?","opts":["Noten kaufen.","Ein Konzert hören.","Instrumente ausprobieren."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Welches Instrument üben sie an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! In der Musikschule hängt der Plan für die Stunden. Hast du ihn gelesen?"},{"speaker":"Lisa","gender":"f","text":"Ich schaue ihn gerade an. Wir passen nicht alle an einem Tag in den kleinen Raum."},{"speaker":"Lukas","gender":"m","text":"Ich übe am Montag die Gitarre. Ich will endlich das neue Stück können."},{"speaker":"Lisa","gender":"f","text":"Die stehen in der Ecke. Will jemand diese Woche Saxophon lernen?"},{"speaker":"Lukas","gender":"m","text":"Saxophon steht nicht auf dem Plan. Dazu ist kein Lehrer da."},{"speaker":"Lisa","gender":"f","text":"Ich setze mich am Dienstag ans Klavier. Die Noten liegen schon bereit."},{"speaker":"Lukas","gender":"m","text":"Dann ist der Raum voll. Tom kommt am Mittwoch und er spielt Schlagzeug."},{"speaker":"Lisa","gender":"f","text":"Schlagzeug ist laut. Hoffentlich ist der Raum dann leer."},{"speaker":"Lukas","gender":"m","text":"Er übt ganz hinten. Wollen wir auch Cello üben?"},{"speaker":"Lisa","gender":"f","text":"Cello üben wir auch nicht."},{"speaker":"Lukas","gender":"m","text":"Sara kommt am Donnerstag mit der Geige."},{"speaker":"Lisa","gender":"f","text":"Geige mag ich gern. Sie spielt leise und sehr schön."},{"speaker":"Lukas","gender":"m","text":"Am Freitag kommt Tim mit der Trompete."},{"speaker":"Lisa","gender":"f","text":"Tim übt die Trompete vor der Feier. Er will ein lautes Stück können."},{"speaker":"Lukas","gender":"m","text":"Dann schreibe ich alles dick auf den Plan."},{"speaker":"Lisa","gender":"f","text":"Ich komme pünktlich zur ersten Stunde."}],"options":[{"letter":"a","text":"Saxophon"},{"letter":"b","text":"Schlagzeug"},{"letter":"c","text":"Gesang"},{"letter":"d","text":"Geige"},{"letter":"e","text":"Gitarre"},{"letter":"f","text":"Flöte"},{"letter":"g","text":"Trompete"},{"letter":"h","text":"Cello"},{"letter":"i","text":"Klavier"}],"items":[{"person":"Montag","correct":"e"},{"person":"Dienstag","correct":"i"},{"person":"Mittwoch","correct":"b"},{"person":"Donnerstag","correct":"d"},{"person":"Freitag","correct":"g"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Mutter","gender":"f","text":"Guten Tag, was kostet der Unterricht im Monat? 80 Euro für alles?"},{"speaker":"Leiter","gender":"m","text":"Einzelunterricht 80 Euro, Gruppe 40 Euro. 120 Euro wäre nur bei zwei Fächern."},{"speaker":"Mutter","gender":"f","text":"Was empfehlen Sie für Anfänger? Die Gruppe für 40 Euro oder einzeln für 80?"},{"speaker":"Leiter","gender":"m","text":"Am Anfang reicht die Gruppe für 40 Euro. Nicht 80 und nicht 120, das ist erst später."},{"speaker":"Mutter","gender":"f","text":"Gut, dann nehmen wir die Gruppe für 40 Euro. Danke."}],"q":"Was kostet der Gruppenunterricht?","opts":["80 Euro.","120 Euro.","40 Euro."],"correct":2},{"lines":[{"speaker":"Vater","gender":"m","text":"Guten Tag, wie oft ist der Unterricht? Eine Stunde, oder nur 15 Minuten?"},{"speaker":"Lehrerin","gender":"f","text":"Einmal pro Woche, 30 Minuten. 60 Minuten wäre für Fortgeschrittene, 15 Minuten ist zu kurz."},{"speaker":"Vater","gender":"m","text":"Reicht das? 30 Minuten klingt wenig, 60 wäre besser, oder?"},{"speaker":"Lehrerin","gender":"f","text":"Ja, 30 Minuten reichen, wenn das Kind zu Hause täglich übt. Nicht 60 und nicht nur 15."},{"speaker":"Vater","gender":"m","text":"Verstehe, dann 30 Minuten plus Üben zu Hause. Danke."}],"q":"Wie lange dauert eine Unterrichtsstunde?","opts":["30 Minuten.","60 Minuten.","15 Minuten."],"correct":0},{"lines":[{"speaker":"Schülerin","gender":"f","text":"Muss ich ein Instrument kaufen? Oder kann ich eins leihen, vielleicht kostenlos?"},{"speaker":"Lehrer","gender":"m","text":"Am Anfang können Sie eins leihen. Kostenlos geht nicht, und kaufen müssen Sie noch nicht."},{"speaker":"Schülerin","gender":"f","text":"Was kostet das Leihen? 15 Euro, oder 30?"},{"speaker":"Lehrer","gender":"m","text":"15 Euro im Monat, nicht 30 und nicht kostenlos. Nach einem Jahr können Sie kaufen."},{"speaker":"Schülerin","gender":"f","text":"Gut, dann leihe ich erst mal für 15 Euro. Danke."}],"q":"Was kostet das Leihen pro Monat?","opts":["15 Euro.","30 Euro.","Kostenlos."],"correct":0},{"lines":[{"speaker":"Mutter","gender":"f","text":"Mein Sohn möchte aufhören. Es ist nicht zu teuer und er ist nicht krank, aber er mag es nicht."},{"speaker":"Lehrerin","gender":"f","text":"Schade, warum denn? Ist es das Geld, oder ist er krank?"},{"speaker":"Mutter","gender":"f","text":"Nein, es ist nicht zu teuer und er ist nicht krank. Er findet das Üben langweilig."},{"speaker":"Lehrerin","gender":"f","text":"Verstehe. Vielleicht ein anderes Instrument? Schlagzeug macht oft mehr Spaß als nur Üben am Tisch."},{"speaker":"Mutter","gender":"f","text":"Gute Idee, das frage ich ihn. Danke."}],"q":"Warum möchte der Sohn aufhören?","opts":["Er ist krank.","Es ist zu teuer.","Er findet das Üben langweilig."],"correct":2},{"lines":[{"speaker":"Schüler","gender":"m","text":"Wann ist das nächste Konzert? Müssen alle spielen, oder spielt niemand?"},{"speaker":"Leiter","gender":"m","text":"In zwei Wochen, am Samstag. Nicht alle müssen, nur wer möchte. Es spielen aber schon einige."},{"speaker":"Schüler","gender":"m","text":"Muss ich auch spielen? Ich habe noch Angst."},{"speaker":"Leiter","gender":"m","text":"Nur wenn du möchtest, kein Zwang. Du musst nicht, und niemand zwingt dich. Wer will, spielt."},{"speaker":"Schüler","gender":"m","text":"Dann schaue ich erst zu. Danke, das beruhigt mich."}],"q":"Muss der Schüler beim Konzert spielen?","opts":["Ja, alle müssen.","Nur wenn er möchte.","Nein, niemand spielt."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Hofmann, einer Musiklehrerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Hofmann, ab welchem Alter sollen Kinder ein Instrument lernen?"},{"speaker":"Hofmann","gender":"f","text":"Mit sechs oder sieben Jahren ist ein guter Start. Aber das Kind muss Lust haben. Zwingen bringt nichts, dann macht es keinen Spaß."},{"speaker":"Reporter","gender":"m","text":"Wie wichtig ist das Üben zu Hause?"},{"speaker":"Hofmann","gender":"f","text":"Sehr wichtig. Besser jeden Tag fünfzehn Minuten als einmal in der Woche lang. Einmal die Woche lange üben ist nicht am besten, das vergessen die Kinder schnell."},{"speaker":"Reporter","gender":"m","text":"Lernen auch Erwachsene bei Ihnen, oder nur Kinder?"},{"speaker":"Hofmann","gender":"f","text":"Ja, immer mehr Erwachsene. Man ist nie zu alt für Musik. Manche kommen nach der Arbeit und sind sehr fleißig."},{"speaker":"Reporter","gender":"m","text":"Ist Musik gut für Kinder in der Schule?"},{"speaker":"Hofmann","gender":"f","text":"Ja, sehr, sie hilft beim Lernen und macht glücklich. Kinder, die musizieren, können sich oft besser konzentrieren."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie Eltern, wenn ein Kind aufhören will?"},{"speaker":"Hofmann","gender":"f","text":"Nicht gleich aufgeben. Vielleicht passt ein anderes Instrument besser. Reden Sie in Ruhe mit dem Kind, und geben Sie ihm noch ein paar Wochen Zeit. Oft kommt die Lust dann wieder, wenn das Stück endlich klappt. Geduld ist hier sehr wichtig."}],"items":[{"q":"Frau Hofmann sagt, mit sechs oder sieben ist ein guter Start.","correct":"ja"},{"q":"Sie meint, einmal pro Woche lang üben ist am besten.","correct":"nein"},{"q":"Auch immer mehr Erwachsene lernen bei ihr.","correct":"ja"},{"q":"Musik hilft Kindern beim Lernen.","correct":"ja"},{"q":"Sie rät, sofort aufzugeben, wenn ein Kind aufhören will.","correct":"nein"}]}]};
